-- Product to category
INSERT INTO product_categories (product_id, category_id)
SELECT p.id, c.id
  FROM (VALUES
    ('aria-top-handle', 'handbags'),
    ('meridian-tote', 'totes'),
    ('halden-satchel', 'crossbody'),
    ('solenne-mini', 'handbags'),
    ('corbel-briefcase', 'laptop-work'),
    ('atlas-weekender', 'travel'),
    ('verso-backpack', 'backpacks'),
    ('linea-bifold', 'wallets'),
    ('plinth-card-case', 'card-cases'),
    ('arc-belt-35', 'belts'),
    ('fine-belt-20', 'belts'),
    ('tessera-key-loop', 'key-accessories'),
    ('coin-pouch', 'pouches'),
    ('folio-pouch', 'pouches'),
    ('zip-around-wallet', 'wallets'),
    ('travel-card-holder', 'card-cases'),
    ('rue-shoulder', 'handbags'),
    ('nomad-sling', 'crossbody'),
    ('ledger-laptop-tote', 'laptop-work'),
    ('dossier-messenger', 'laptop-work'),
    ('cabin-duffle', 'travel'),
    ('washbag', 'travel')
  ) AS v (product_slug, category_slug)
  JOIN products p ON p.slug = v.product_slug
  JOIN categories c ON c.slug = v.category_slug
ON CONFLICT DO NOTHING;

-- Collections (manual membership, copied from the storefront's filters)
INSERT INTO collections (slug, title, eyebrow, intro, kind, hero_media_id, sort_order, status)
SELECT v.slug, v.title, v.eyebrow, v.intro, 'MANUAL'::collection_kind, m.id, v.sort_order, 'PUBLISHED'::publish_status
  FROM (VALUES
    ('all', 'The Collection', 'Everything', 'Every piece in the current house collection, from key loops to weekenders.', 'dev/catalogue/hero.jpg', 0),
    ('new-in', 'New In', 'Autumn / Winter', 'Recent arrivals: sculpted handles, softer totes and a new weekender.', 'dev/catalogue/hero.jpg', 1),
    ('women', 'Women', 'Womenswear', 'Top-handles, shoulder bags, totes and small leather goods.', 'dev/catalogue/women.jpg', 2),
    ('men', 'Men', 'Menswear', 'Briefcases, backpacks, belts and wallets with quiet hardware.', 'dev/catalogue/men.jpg', 3),
    ('bags', 'Bags', 'Carry', 'From the mini to the weekender — shapes for every distance.', 'dev/catalogue/women.jpg', 4),
    ('small-leather-goods', 'Small Leather Goods', 'Everyday objects', 'Wallets, card cases, belts and pouches. Considered gifts start at ₹590.', 'dev/catalogue/slg.jpg', 5),
    ('work-travel', 'Work & Travel', 'In transit', 'Laptop bags, backpacks, duffles and wash bags built for movement.', 'dev/catalogue/travel.jpg', 6),
    ('gifts', 'The Gift Edit', 'Under ₹6,000', 'Small objects, well made. Pieces chosen for giving.', 'dev/catalogue/slg.jpg', 7)
  ) AS v (slug, title, eyebrow, intro, hero_key, sort_order)
  JOIN media_assets m ON m.storage_key = v.hero_key
ON CONFLICT (slug) DO NOTHING;

